// Generated by Decentraland Studio. Do not edit: this copy is kept in sync with your editor version.
// Windows: the UI the player interacts with for a moment (shop, recipe choice, dialog, results), as opposed to the
// HUD (./hudKit), which stays on screen during play. While a window is open it may take the whole screen.
// On a phone it fills the interactable area edge to edge with thumb-sized buttons and little padding: every pixel
// holds content. On desktop it is centred, at most `maxWidth` (default 960) wide, and as tall as its content.
//
// mountWindow({ open, close, render }) places a window in the shared layout (./hudLayout 'modal' slot) and returns
// its removal. While open() answers true the screen behind it dims, a tap on it calls close(), and the phone's
// touch controls are hidden. Make close() the one way it closes (it is also where its close sound plays).
//   let shopOpen = false
//   mountWindow({ open: () => shopOpen, close: () => { shopOpen = false }, render: () =>
//     <UiWindow id="shop" title="Shop" onClose={() => { shopOpen = false }}>
//       <UiChoiceGrid id="shop" choices={items.map((item) => ({ label: item.name, detail: `${item.price} coins`,
//         image: item.icon, disabled: coins < item.price, onClick: () => buy(item) }))} />
//     </UiWindow> })
// <UiWindow id title? onClose? dense? maxWidth?> is the panel: a title row with a close button when onClose is
//   given, then its children, which fill the rest. dense steps text and buttons down one size (uiSizes in
//   ./uiComponents) for a window with a lot to fit. The panel's elementId is `id`.
// <UiChoiceGrid id choices columns? dense?> is a grid of pressable tiles filling the width: label, optional detail
//   line and image, `disabled` greyed out. Columns default to 2 on a phone and 3 on desktop. Tile i is `${id}-choice-i`.
// <UiWindowActions id actions dense?> is the bottom row of buttons, the primary one last (on the right, nearest
//   the right thumb) and taller. At most three. Button i is `${id}-action-i`.
// <UiWindowText text dense? muted?> is a paragraph sized for the window.
import ReactEcs, { UiEntity } from '@dcl/sdk/react-ecs'
import { isMobile } from '@dcl/sdk/platform'
import { sceneUiTheme } from './uiTheme'
import { ThemedEntity, UiButton, UiText, uiSizes } from './uiComponents'
import { addHudItem } from './hudLayout'
import type { UiTheme } from './pure/uiTheme'

export function mountWindow(options: { open(): boolean; close(): void; render(): ReactEcs.JSX.Element | null; order?: number }): () => void {
  return addHudItem('modal', options.render, { open: options.open, close: options.close, order: options.order })
}

export function UiWindow(props: { id: string; title?: string; onClose?: () => void; dense?: boolean; maxWidth?: number; theme?: UiTheme; children?: ReactEcs.JSX.ReactNode }) {
  const theme = props.theme ?? sceneUiTheme()
  const size = uiSizes('window', { dense: props.dense })
  const phone = isMobile()
  const header = props.title !== undefined || props.onClose !== undefined
  const headerHeight = props.onClose !== undefined ? size.button : Math.round(size.title * 1.5)
  const frame = phone ? { width: '100%' as const, height: '100%' as const } : { width: '90%' as const, maxWidth: props.maxWidth ?? 960, height: 'auto' as const, maxHeight: '90%' as const }
  return <ThemedEntity uiTransform={{ elementId: props.id, ...frame, flexDirection: 'column', padding: size.pad, borderRadius: phone ? 0 : theme.radius,
    borderWidth: phone ? 0 : 1, borderColor: theme.border, pointerFilter: 'block' }} uiBackground={{ color: theme.panel }}>
    {header && <UiEntity uiTransform={{ width: '100%', height: headerHeight, flexDirection: 'row', alignItems: 'center', flexShrink: 0, margin: { bottom: size.gap }, pointerFilter: 'none' }}>
      <UiText value={props.title ?? ''} color={theme.text} size={size.title} height={headerHeight} uiTransform={{ width: 'auto', flexGrow: 1, elementId: `${props.id}-title` }} />
      {props.onClose !== undefined && <UiButton theme={theme} label="X" secondary onClick={props.onClose}
        uiTransform={{ width: size.button, height: size.button, flexShrink: 0, elementId: `${props.id}-close` }} />}
    </UiEntity>}
    <UiEntity uiTransform={{ width: '100%', flexGrow: 1, flexDirection: 'column', pointerFilter: 'none' }}>{props.children}</UiEntity>
  </ThemedEntity>
}

export function UiWindowText(props: { text: string; dense?: boolean; muted?: boolean; lines?: number; theme?: UiTheme }) {
  const theme = props.theme ?? sceneUiTheme()
  const size = uiSizes('window', { dense: props.dense })
  const fontSize = props.muted === true ? size.small : size.text
  return <UiText value={props.text} color={props.muted === true ? theme.muted : theme.text} size={fontSize}
    height={Math.round(fontSize * 1.35 * (props.lines ?? 1))} uiTransform={{ flexShrink: 0 }} />
}

export interface UiChoice { label: string; detail?: string; image?: string; disabled?: boolean; onClick(): void }

export function UiChoiceGrid(props: { id: string; choices: UiChoice[]; columns?: number; dense?: boolean; theme?: UiTheme }) {
  const theme = props.theme ?? sceneUiTheme()
  const size = uiSizes('window', { dense: props.dense })
  const columns = Math.max(1, props.columns ?? (isMobile() ? 2 : 3))
  const height = Math.max(size.primary, Math.round(size.text * 1.35 + size.small * 1.35 + 2 * size.pad))
  const image = height - 2 * size.pad
  return <UiEntity uiTransform={{ width: '100%', flexDirection: 'row', flexWrap: 'wrap', flexShrink: 0, pointerFilter: 'none' }}>
    {props.choices.map((choice, i) => <UiEntity key={i} uiTransform={{ width: `${100 / columns}%`, height: height + size.gap, padding: { right: (i + 1) % columns === 0 ? 0 : size.gap, bottom: size.gap }, pointerFilter: 'none' }}>
      <ThemedEntity uiTransform={{ elementId: `${props.id}-choice-${i}`, width: '100%', height, flexDirection: 'row', alignItems: 'center', padding: size.pad,
        borderRadius: theme.radius, pointerFilter: 'block' }} uiBackground={{ color: choice.disabled === true ? theme.panel : theme.surface }}
        onMouseDown={() => { if (choice.disabled !== true) choice.onClick() }}>
        {choice.image !== undefined && <UiEntity uiTransform={{ width: image, height: image, flexShrink: 0, margin: { right: size.gap }, pointerFilter: 'none' }}
          uiBackground={{ texture: { src: choice.image }, textureMode: 'stretch' }} />}
        <UiEntity uiTransform={{ width: 'auto', flexGrow: 1, height: '100%', flexDirection: 'column', justifyContent: 'center', pointerFilter: 'none' }}>
          <UiText value={choice.label} color={choice.disabled === true ? theme.muted : theme.text} size={size.text} height={Math.round(size.text * 1.35)} />
          {choice.detail !== undefined && <UiText value={choice.detail} color={theme.muted} size={size.small} height={Math.round(size.small * 1.35)} />}
        </UiEntity>
      </ThemedEntity>
    </UiEntity>)}
  </UiEntity>
}

export interface UiWindowAction { label: string; primary?: boolean; disabled?: boolean; onClick(): void }

export function UiWindowActions(props: { id: string; actions: UiWindowAction[]; dense?: boolean; theme?: UiTheme }) {
  const theme = props.theme ?? sceneUiTheme()
  const size = uiSizes('window', { dense: props.dense })
  const actions = [...props.actions.filter((action) => action.primary !== true), ...props.actions.filter((action) => action.primary === true)].slice(0, 3)
  const height = actions.some((action) => action.primary === true) ? size.primary : size.button
  return <UiEntity uiTransform={{ width: '100%', height, flexDirection: 'row', alignItems: 'flex-end', flexShrink: 0, margin: { top: size.gap }, pointerFilter: 'none' }}>
    {actions.map((action, i) => <UiEntity key={i} uiTransform={{ width: 'auto', flexGrow: 1, height: action.primary === true ? size.primary : size.button,
      margin: { left: i === 0 ? 0 : size.gap }, pointerFilter: 'none' }}>
      <UiButton theme={theme} label={action.label} secondary={action.primary !== true} disabled={action.disabled} onClick={action.onClick}
        uiTransform={{ elementId: `${props.id}-action-${i}`, height: '100%' }} />
    </UiEntity>)}
  </UiEntity>
}
